using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Accounts.Admin;using OrcaFacil.Application.Auth;using OrcaFacil.Domain.Entities;using OrcaFacil.Domain.Enums;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.AccountAdmin.Users;[Authorize(Policy="AccountAdmin")]public sealed class NewModel(OrcaFacilDbContext db,ICurrentAccountService current,IPasswordHasher hasher,LoginIdentifierService identifiers):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public IEnumerable<string>Profiles=>ProfilePermissionMatrix.AccountProfiles.Where(x=>ProfilePermissionMatrix.CanAssign(current.AccountRoleCode??"",x));public sealed class InputModel{[Required,StringLength(180)]public string Name{get;set;}="";[Required,EmailAddress]public string Email{get;set;}="";public string? Document{get;set;}[Required,MinLength(10)]public string TemporaryPassword{get;set;}="";[Required]public string Profile{get;set;}="ReadOnly";}public async Task<IActionResult>OnPostAsync(CancellationToken ct){if(current.AccountId is not Guid account)return Forbid();if(!ModelState.IsValid)return Page();if(!ProfilePermissionMatrix.CanAssign(current.AccountRoleCode??"",Input.Profile)){ModelState.AddModelError("Input.Profile","Você não pode atribuir este perfil.");return Page();}var email=Input.Email.Trim().ToLowerInvariant();var user=await db.Users.SingleOrDefaultAsync(x=>x.Email==email&&!x.IsDeleted,ct);if(user is null){NormalizedLoginIdentifier? doc=null;if(!string.IsNullOrWhiteSpace(Input.Document)){try{doc=identifiers.Normalize(Input.Document);if(doc.Kind==LoginIdentifierKind.Email)ModelState.AddModelError("Input.Document","Informe um CPF ou CNPJ.");else if(await db.Users.AnyAsync(x=>x.DocumentNumber==doc.Value&&!x.IsDeleted,ct))ModelState.AddModelError("Input.Document","CPF/CNPJ já cadastrado.");}catch(ArgumentException ex){ModelState.AddModelError("Input.Document",ex.Message);}}if(!ModelState.IsValid)return Page();user=new UserAccount{Name=Input.Name.Trim(),Email=email,PasswordHash=hasher.Hash(Input.TemporaryPassword),MustChangePassword=true,DocumentNumber=doc?.Value,DocumentType=doc is null?null:doc.Kind==LoginIdentifierKind.Cnpj?BrazilianDocumentType.CNPJ:BrazilianDocumentType.CPF};db.Users.Add(user);}if(await db.AccountMembers.AnyAsync(x=>x.AccountId==account&&x.UserId==user.Id&&!x.IsDeleted,ct)){ModelState.AddModelError(string.Empty,"Este usuário já pertence à conta.");return Page();}var member=new AccountMember{AccountId=account,UserId=user.Id,RoleCode=Input.Profile};member.Join();db.AccountMembers.Add(member);db.AccountModuleAuditLogs.Add(new(){AccountId=account,ActorUserId=current.UserId,Action="AccountUserCreated",EntityType=nameof(AccountMember),EntityId=member.Id.ToString(),Summary=$"Usuário vinculado com perfil {Input.Profile}.",CorrelationId=HttpContext.TraceIdentifier});await db.SaveChangesAsync(ct);return RedirectToPage("Index");}}
